package com.typheye.wgpro.ui.function.device;
import android.os.Bundle; import android.view.View; import android.widget.TextView; import android.widget.Toast; import androidx.appcompat.app.AppCompatActivity; import androidx.appcompat.widget.Toolbar; import com.google.android.material.button.MaterialButton; import com.typheye.wgpro.R; import com.typheye.wgpro.core.xms.UIParams; import com.typheye.wgpro.data.DeviceDatabase; import com.typheye.wgpro.ui.main.MainActivity; import com.typheye.wgpro.utils.AppUtils;
public class AddDeviceActivity extends AppCompatActivity {
 @Override protected void onCreate(Bundle state){super.onCreate(state);AppUtils.useScreenCutArea(getWindow(),this);setContentView(R.layout.activity_add_device);AppUtils.applyMainWindowInsets(findViewById(R.id.app_bar_layout),findViewById(R.id.add_device_content));Toolbar toolbar=findViewById(R.id.add_device_toolbar);setSupportActionBar(toolbar);toolbar.setNavigationOnClickListener(v->finish());UIParams p=MainActivity.current_params;TextView title=findViewById(R.id.add_device_title),subtitle=findViewById(R.id.add_device_subtitle),initial=findViewById(R.id.add_device_initial);MaterialButton add=findViewById(R.id.button_add_device);boolean found=p!=null&&p.connected&&p.connected_device_id!=null&&!p.connected_device_id.isEmpty();if(found){title.setText(p.connected_device_name);subtitle.setText("已通过 Xiaomi Wearable SDK 检测到此设备\n添加后可查看状态与设备信息");initial.setText(p.connected_device_name.substring(0,1).toUpperCase());add.setVisibility(View.VISIBLE);add.setOnClickListener(v->{try(DeviceDatabase db=new DeviceDatabase(this)){db.upsert(p.connected_device_id,p.connected_device_name,"xiaomi",true);}Toast.makeText(this,"设备已添加",Toast.LENGTH_SHORT).show();finish();});}else{title.setText("未发现可添加设备");subtitle.setText("请先连接小米手环或手表，再返回此页面添加。");initial.setText("+");}}
}
